CL_OLD = 'abstentions - an override that had picked it out in amber is removed. A leftover unused style\nrule from an earlier design pass is deleted.\n'
CL_NEW = "abstentions - an override that had picked it out in amber is removed. A leftover unused style\nrule from an earlier design pass is deleted.\n\n**One paragraph per case, three per row.** Each overview tile now reads as a single paragraph: what\nthe case tests, fully explained; that case's own facts - vessels tracked and replayed, the nearest\nvessel at image time and how far away - and what forward replay concluded, with its fit and\nvariant wins. So no two cases read alike. The grid is fixed at three per row (nine cases make an\nexact 3 x 3), dropping to two or one only on narrow windows.\n"
read = lambda p: open(p, encoding="utf-8").read()
sha = lambda p: hashlib.sha256(open(p, "rb").read()).hexdigest()
writes, skipped = {}, 0
for p, v in REPLACE.items():
    if not os.path.exists(p): abort(f"{p} is missing")
    if read(p) == v["after"]: skipped += 1
    elif sha(p) == v["before"]: writes[p] = v["after"]
    else: abort(f"{p} is not the version this patch was written for; send its sha256")
cl = read("CHANGELOG.md")
if CL_NEW in cl: skipped += 1
elif cl.count(CL_OLD) == 1: writes["CHANGELOG.md"] = cl.replace(CL_OLD, CL_NEW, 1)
else: abort("CHANGELOG.md: the patch 50 entry this appends after was not found - apply patch 50 first")
for p, text in writes.items():
    open(p, "w", encoding="utf-8").write(text)
print(f"patch 51: {len(writes)} files written, {skipped} already in place.")
